create or replace function public.factory_persist_product_stage(p_run_id uuid,p_stage text,p_output jsonb) returns jsonb language plpgsql security invoker set search_path='' as $$ declare v_task_id uuid;v_project_id uuid;v_version integer;v_created_tasks integer:=0;v_item jsonb;v_external_key text;begin if p_stage not in ('discovery','specification','planning') then raise exception 'unsupported product stage';end if;select r.task_id,t.project_id into v_task_id,v_project_id from public.factory_runs r join public.factory_tasks t on t.id=r.task_id where r.id=p_run_id;if v_project_id is null then raise exception 'run not found';end if;if p_stage='discovery' then update public.factory_product_specs set spec=jsonb_set(spec,'{discovery}',coalesce(p_output,'{}'::jsonb),true) where project_id=v_project_id and version=(select max(version) from public.factory_product_specs where project_id=v_project_id);update public.factory_projects set lifecycle_stage='specification',updated_at=now() where id=v_project_id;elsif p_stage='specification' then select coalesce(max(version),0)+1 into v_version from public.factory_product_specs where project_id=v_project_id;insert into public.factory_product_specs(project_id,version,status,spec) values(v_project_id,v_version,'candidate',coalesce(p_output,'{}'::jsonb));update public.factory_projects set lifecycle_stage='planning',updated_at=now() where id=v_project_id;else update public.factory_projects set lifecycle_stage='implementation',manifest=manifest||jsonb_build_object('engineering_plan',coalesce(p_output,'{}'::jsonb)),updated_at=now() where id=v_project_id;for v_item in select value from jsonb_array_elements(coalesce(p_output->'tasks','[]'::jsonb)) loop v_external_key:='plan-'||substr(md5(coalesce(v_item->>'title',v_item::text)),1,16);if not exists(select 1 from public.factory_tasks where project_id=v_project_id and external_key=v_external_key) then insert into public.factory_tasks(project_id,parent_task_id,external_key,title,description,status,complexity,risk,acceptance_criteria,depends_on) values(v_project_id,v_task_id,v_external_key,coalesce(nullif(v_item->>'title',''),'Planned task'),v_item->>'description','queued',case when v_item->>'complexity' in ('low','medium','high','very_high') then v_item->>'complexity' else 'medium' end,coalesce(v_item->'risk','{}'::jsonb),coalesce(v_item->'acceptance_criteria','[]'::jsonb),coalesce(v_item->'depends_on','[]'::jsonb));v_created_tasks:=v_created_tasks+1;end if;end loop;end if;insert into public.factory_audit_events(project_id,task_id,run_id,actor_type,actor_ref,event_type,payload) values(v_project_id,v_task_id,p_run_id,'system','runtime-worker','product.stage.persisted',jsonb_build_object('stage',p_stage,'created_tasks',v_created_tasks));return jsonb_build_object('project_id',v_project_id,'stage',p_stage,'created_tasks',v_created_tasks);end;$$;
revoke all on function public.factory_persist_product_stage(uuid,text,jsonb) from public,anon,authenticated;grant execute on function public.factory_persist_product_stage(uuid,text,jsonb) to service_role;
